style.css:
@-moz-document domain("open.spotify.com") {
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: url("https://i.pinimg.com/1200x/e8/73/86/e8738644ceea3c8a3d29a798e71004d9.jpg") center / cover fixed;
  filter: brightness(0.8) saturate(1.2);
  z-index: -1;
  pointer-events: none;
}

/* Strip all backgrounds */
*,
[class*="Root"],
[class*="root"],
[class*="main"],
[class*="nav"],
[class*="sidebar"],
[class*="contentSpacing"] {
  background-color: transparent !important;
  background-image: none !important;
}

/* Keep text white and readable */
* {
  color: white !important;
  text-shadow: 0 1px 3px rgba(0,0,0,0.8) !important;
}

/* Navbar and sidebar slight dark tint */
nav,
[class*="NavBar"],
[class*="sidebar"],
[class*="LeftSidebar"],
[class*="now-playing-bar"] {
  background-color: rgba(0,0,0,0.45) !important;
  backdrop-filter: blur(8px) !important;
}

/* Now playing bar at bottom */
[class*="now-playing-bar"],
footer,
[class*="Footer"] {
  background-color: rgba(0,0,0,0.5) !important;
  backdrop-filter: blur(10px) !important;
}

/* Search bar and inputs */
input,
[class*="SearchInput"],
[class*="encore-text-input"] {
  background-color: rgba(0,0,0,0.4) !important;
  border: 1px solid rgba(255,255,255,0.2) !important;
  color: white !important;
}

/* Cards and album tiles */
[class*="CardInner"],
[class*="card"],
[class*="Card"] {
  background-color: rgba(0,0,0,0.3) !important;
  backdrop-filter: blur(6px) !important;
}

/* Play button keep green */
[class*="playButton"],
[class*="PlayButton"],
.encore-positive-set {
  color: #1db954 !important;
}

/* Progress bar keep green */
[class*="progress-bar"],
[class*="ProgressBar"] {
  background-color: #1db954 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 4px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.2) !important;
  border-radius: 4px !important;
}
}
